package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamReproductiveBank2 {
    private const val T = "නව යොවුන් විය, ප්‍රජනක සෞඛ්‍යය හා ලිංගික සම්ප්‍රේෂණ ආසාදන"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("මිනිසාගේ සාමාන්‍ය දේහ සෛලයක වර්ණදේහ 46ක් (යුගල 23ක්) අඩංගු වන අතර පරිණත ශුක්‍රාණුවක හෝ ඩිම්බයක අඩංගු වර්ණදේහ සංඛ්‍යාව කීයද?", "වර්ණදේහ 23කි (ඒකගුණ හෙවත් n)", "වර්ණදේහ 46කි", "වර්ණදේහ 12කි", "වර්ණදේහ 92කි", "ප්‍රජනක සෛල හෙවත් ජන්මාණු තුළ ඌනන විභාජනය නිසා වර්ණදේහ සංඛ්‍යාව අඩක් හෙවත් 23ක් දක්වා අඩු වේ."),
        q("වෘෂණ තුළ ශුක්‍රාණු ජනනය සිදුවන සියුම් දඟර ගැසුණු නාලිකා විශේෂය කුමක්ද?", "ශුක්‍රධර නාලිකා (Seminiferous tubules)", "අපිවෘෂණය", "ශුක්‍ර ප්‍රණාලය", "කූපර් නාලිකා", "ශුක්‍රධර නාලිකා බිත්තියේ ඇති ප්‍රාථමික සෛල ඌනන විභාජනයෙන් බෙදී ශුක්‍රාණු නිපදවේ."),
        q("ශුක්‍රධර නාලිකා තුළ වැඩෙන ශුක්‍රාණුවලට පෝෂණය සහ ආරක්ෂාව සපයන සුවිශේෂී සෛල වර්ගය කුමක්ද?", "සර්ටෝලි සෛල (Sertoli cells)", "ලීඩිග් සෛල", "ස්නායු සෛල", "රතු රුධිර සෛල", "සර්ටෝලි සෛල 'හෙද සෛල' ලෙසද හඳුන්වන අතර ඒවා ශුක්‍රාණු පරිණත වීමට අවශ්‍ය පෝෂණය සපයයි."),
        q("පිරිමි වෘෂණ තුළ ටෙස්ටොස්ටෙරෝන් හෝමෝනය නිපදවනු ලබන අන්තරාල සෛල හඳුන්වන්නේ කෙසේද?", "ලීඩිග් සෛල (Leydig cells)", "සර්ටෝලි සෛල", "ෆොලිකල සෛල", "සුදු රුධිර සෛල", "ශුක්‍රධර නාලිකා අතර පිහිටි ලීඩිග් සෛල මගින් පිරිමි ලිංගික හෝමෝනය නිපදවයි."),
        q("නව යොවුන් වියේදී පිරිමි දරුවන් තුළ සිදුවන සමාජීය හා මානසික සංවර්ධන ලක්ෂණයක් වන්නේ කුමක්ද?", "දෙමාපියන්ගෙන් මිදී ස්වාධීන වීමට උත්සාහ කිරීම සහ සමවයස් මිතුරු කණ්ඩායම්වලට නැඹුරු වීම", "තනිව හුදකලා වීම පමණක්", "ළදරු චර්යාවන් පෙන්වීම", "සමාජයෙන් සම්පූර්ණයෙන්ම ඈත් වීම", "නව යොවුන් වියේදී අනන්‍යතාවය සෙවීම සහ මිතුරු ඇසුර ප්‍රමුඛ වීම සාමාන්‍ය ලක්ෂණයකි."),
        q("නව යොවුන් දරුවන් අවදානම් සහිත චර්යාවලට (වේගයෙන් රිය පැදවීම, මත්ද්‍රව්‍ය අත්හදා බැලීම) පෙළඹීමට බලපාන ස්නායු විද්‍යාත්මක හේතුව කුමක්ද?", "තීරණ ගන්නා පූර්ව חזיתීය බාහිකය (Prefrontal Cortex) පූර්ණ පරිණත වීමට පෙර චිත්තවේග පාලනය කරන ලිම්බික් පද්ධතිය ක්‍රියාත්මක වීම", "මොළයේ සෛල අඩුවීම", "ස්නායු පද්ධතිය අඩපණ වීම", "හිස විශාල වීම", "චිත්තවේග පාලනය සහ තීරණ ගැනීමේ හැකියාව පරිණත වන්නේ අවුරුදු 20-25 පමණ වන විටය."),
        q("නව යොවුන් වියේදී මිතුරන්ගේ බලපෑමට (Peer Pressure) යටත්ව වැරදි දේ කිරීමට ඇතිවන පෙළඹවීමෙන් ආරක්ෂා වීමට අවශ්‍ය වැදගත්ම ජීවන නිපුණතාව කුමක්ද?", "නොපැකිලිව අකමැත්ත ප්‍රකාශ කිරීමේ හෙවත් 'එපා' කීමේ ප්‍රතික්ෂේප කිරීමේ නිපුණතාව (Refusal Skills / Assertiveness)", "මිතුරන් කියන සියල්ල පිළිගැනීම", "කාමරයේ සැඟවීම", "ප්‍රචණ්ඩ ලෙස හැසිරීම", "තමාගේ ප්‍රතිපත්තිවලට පටහැනි අහිතකර යෝජනා ස්ථිරව හා ගෞරවාන්විතව ප්‍රතික්ෂේප කිරීමට හැකි විය යුතුය."),
        q("ගර්භණී සමයේ මුල් සති 12 තුළ (පළමු ත්‍රෛමාසිකයේ) කලලයේ ප්‍රධාන අවයව සෑදෙන ක්‍රියාවලිය කුමක්ද?", "අවයව ජනනය (Organogenesis)", "රෝපණය පමණි", "ප්‍රසූතිය", "මව්කිරි සෑදීම", "මුල් මාස 3 තුළ හෘදය, මොළය ඇතුළු සියලුම ප්‍රධාන අවයව සෑදෙන බැවින් ඖෂධ හා ආසාදනවලින් ඉතා පරිස්සම් විය යුතුය."),
        q("කලලයේ ස්නායු නාල විකෘතිතා (Neural Tube Defects / Spina bifida) වැළැක්වීම සඳහා ගැබ් ගැනීමට පෙර සිටම කාන්තාවන්ට ලබාදෙන අත්‍යවශ්‍ය විටමිනය කුමක්ද?", "ෆෝලික් අම්ලය (Folic Acid)", "විටමින් A", "විටමින් C", "විටමින් D", "ගැබ් ගැනීමට මාසයකට පෙර සිට සහ මුල් මාස 3 තුළ දිනපතා ෆෝලික් අම්ලය ගැනීමෙන් ස්නායු විකෘතිතා 70%කින් වළකී."),
        q("ගර්භණී මවකට රක්තහීනතාව වැළැක්වීම සඳහා සෞඛ්‍ය සායන මගින් නොමිලේ ලබාදෙන ඛනිජ ලවණ පෙති වර්ගය කුමක්ද?", "යකඩ පෙති (Iron Tablets) සහ කැල්සියම් පෙති", "සින්ක් පෙති පමණි", "සෝඩියම් පෙති", "මැග්නීසියම් පෙති", "මවගේ සහ කලලයේ රුධිර පරිමාව වැඩිවීම නිසා ඇතිවන රක්තහීනතාව වැළැක්වීමට යකඩ පෙති දෙනු ලැබේ."),
        q("ගැබ් ගැනීමට අපේක්ෂා කරන තරුණියක් විවාහයට පෙර ලබාගත යුතු කලලයට ඇස් අන්ධභාවය හා බිහිරි බව ඇතිවීම වළක්වන එන්නත කුමක්ද?", "රුබෙල්ලා එන්නත (Rubella Vaccine)", "පෝලියෝ එන්නත", "BCG එන්නත", "කොලරා එන්නත", "ගර්භණී සමයේ රුබෙල්ලා (ජර්මන් සරම්ප) වැළඳුනහොත් කලලයට බරපතළ සහජ විකෘතිතා හටගනී."),
        q("සංසේචිත ඩිම්බය ගර්භාෂය තුළ නොව පැපොලෝපීය නාලය තුළම තැන්පත් වී වර්ධනය වීම හඳුන්වන්නේ කෙසේද?", "විස්ථාපිත ගර්භණීභාවය (Ectopic Pregnancy)", "සාමාන්‍ය ගැබ් ගැනීම", "බහු ගැබ් ගැනීම", "නොමේරූ දරු උපත", "නාලය තුළ කලලය වැඩෙන විට නාලය පුපුරා මවට මාරාන්තික අභ්‍යන්තර රුධිර වහනයක් සිදුවිය හැක."),
        q("ගර්භණී සමයේදී රුධිර පීඩනය භයානක ලෙස ඉහළ යාම සහ මුත්‍ර සමග ප්‍රෝටීන් පිටවීම හඳුන්වන රෝගී තත්ත්වය කුමක්ද?", "ප්‍රී-එක්ලැම්ප්සියාව හෙවත් ගර්භණී විෂවීම (Pre-eclampsia)", "ගර්භණී දියවැඩියාව", "මී උණ", "ඇදුම", "පූර්ව ප්‍රසව සායනවලදී නිතර රුධිර පීඩනය හා මුත්‍ර පරීක්ෂා කරන්නේ මෙම භයානක තත්ත්වය කල්තියා හඳුනා ගැනීමටයි."),
        q("යොවුන් වියේ දැරියකගේ නොමේරූ ශ්‍රෝණි අස්ථි නිසා දරුවාගේ හිස පිටතට ඒමට නොහැකිව සිරවීමෙන් හටගන්නා දරුණු තත්ත්වය කුමක්ද?", "අවහිර වූ ප්‍රසූතිය (Obstructed Labour)", "ක්ෂණික ප්‍රසූතිය", "ස්වභාවික ප්‍රසූතිය", "වේදනා රහිත ප්‍රසූතිය", "අවහිර වූ ප්‍රසූතිය නිසා ගර්භාෂය පුපුරා යාම සහ යෝනි-මුත්‍ර මාර්ග අතර සිදුරු (Fistula) හටගැනීම සිදුවිය හැක."),
        q("අක්මාව ආසාදනය කර සිරෝසිස් සහ අක්මා පිළිකා ඇති කරන ලිංගිකව හා රුධිරයෙන් බෝවන වෛරස් රෝගය කුමක්ද?", "හෙපටයිටිස් B (Hepatitis B)", "හෙපටයිටිස් A", "ඩෙංගු", "මැලේරියාව", "හෙපටයිටිස් B වෛරසය ලිංගික තරල හා රුධිරය මගින් සම්ප්‍රේෂණය වන අතර ඒ සඳහා සාර්ථක එන්නතක් පවතී."),
        q("ට්‍රයිකොමෝනාස් වැජිනාලිස් (Trichomonas vaginalis) නම් ප්‍රොටෝසෝවා පරපෝෂිතයා මගින් බෝවන ආසාදනය කුමක්ද?", "ට්‍රයිකොමෝනියාසිස් (Trichomoniasis)", "සිෆිලිස්", "ගොනෝරියාව", "ඒඩ්ස්", "මෙම ආසාදනයේදී යෝනි මාර්ගයෙන් පෙණ සහිත දුර්ගන්ධවත් කොළ-කහ පැහැති ශ්‍රාවයක් පිටවීම හා දැඩි කැසීම හටගනී."),
        q("කාන්තාවන්ගේ යෝනි මාර්ගයේ දිලීර ආසාදනයක් (Candidiasis / Thrush) ඇති කරන ප්‍රධාන ක්ෂුද්‍ර ජීවියා කවුරුන්ද?", "කැන්ඩිඩා ඇල්බිකන්ස් (Candida albicans)", "බැක්ටීරියා", "වෛරස", "ඇමීබා", "කැන්ඩිඩා යීස්ට් දිලීරය මගින් කිරි කැටිති වැනි සුදු පැහැති ශ්‍රාවයක් සහ තදබල කැසීමක් ඇතිවේ."),
        q("ලිංගික සම්ප්‍රේෂණ ආසාදනයක් නොවන නමුත් ප්‍රතිජීවක භාවිතය හෝ දියවැඩියාව නිසා යෝනි මාර්ගයේ ස්වභාවික ක්ෂුද්‍ර ජීවී සමතුලිතතාව බිඳී යාමෙන් හටගන්නේ කුමක්ද?", "කැන්ඩිඩියාසිස් හෙවත් යීස්ට් ආසාදනය (Candidiasis)", "ගොනෝරියාව", "සිෆිලිස්", "හර්පීස්", "කැන්ඩිඩා යනු සාමාන්‍යයෙන් සම මතුපිට සිටින දිලීරයක් වන අතර ප්‍රතිශක්තිය අඩු වූ විට රෝගී තත්ත්ව ඇති කරයි."),
        q("පිරිමි කොන්ඩමයක් (Condom) නිවැරදිව භාවිත කිරීමේදී පියවරක් නොවන වැරදි ක්‍රියාව කුමක්ද?", "පැකට්ටුව කතුරකින් හෝ දත්වලින් සපා කැපීම", "කල් ඉකුත්වීමේ දිනය පරීක්ෂා කිරීම", "ඉදිරිපස වායු බුබුල තද කර වාතය ඉවත් කිරීම", "සංසර්ගයෙන් පසු ලිහිල් වීමට පෙර රඳවාගෙන ඉවත් කිරීම", "දත්වලින් හෝ කතුරෙන් කැපීමේදී කොන්ඩමය සීරී හෝ සිදුරු වී ආරක්ෂාව බිඳ වැටේ."),
        q("පිරිමි කොන්ඩමයේ අග ඇති නෙරා ගිය කුඩා කුටීරයේ (Reservoir tip) වාතය මිරිකා ඉවත් කර පැළඳිය යුත්තේ මන්ද?", "ශුක්‍ර තරලය රැඳවීමට ඉඩ තැබීමට සහ වාතය නිසා කොන්ඩමය පිපිරී යාම වැළැක්වීමට", "අලංකාරය සඳහා", "ප්‍රමාණය කුඩා කිරීමට", "කිසිදු හේතුවක් නැත", "වාතය ඉවත් නොකළහොත් ශුක්‍ර මෝචනයේදී ඇතිවන පීඩනයෙන් කොන්ඩමය පුපුරා ශුක්‍රාණු පිටතට කාන්දු විය හැක."),
        q("කාන්තාවන් සඳහා නිපදවා ඇති යෝනි මාර්ගය තුළට ඇතුළත් කරන අභ්‍යන්තර කොන්ඩමය හඳුන්වන්නේ කෙසේද?", "කාන්තා කොන්ඩමය හෙවත් ෆෙමිඩොම් (Female Condom / Femidom)", "ලූපය", "හෝමෝන බද්ධය", "ඩයප්‍රමය", "කාන්තා කොන්ඩමය මගින්ද ලිංගික ආසාදන හා අනවශ්‍ය ගැබ් ගැනීම් වළක්වා ගත හැක."),
        q("දිනපතා එකම වේලාවට ගත යුතු ඊස්ට්‍රජන් සහ ප්‍රොජෙස්ටරෝන් හෝමෝන අඩංගු කාන්තා උපත් පාලන ක්‍රමය කුමක්ද?", "මිශ්‍ර මුඛ උපත් පාලන පෙති (Combined Oral Contraceptive Pills)", "හදිසි පෙති", "කොන්ඩම්", "වාසෙක්ටමි", "මුඛ පෙති මගින් ඩිම්බ මෝචනය වැළැක්වීම සහ ගැබ්ගෙල ශ්ලේෂ්මල ඝන කිරීම මගින් ගැබ් ගැනීම වළක්වයි."),
        q("කාන්තාවකගේ අතේ සම යට බද්ධ කර වසර 3 සිට 5 දක්වා හෝමෝන මුදාහරින උපත් පාලන ක්‍රමය කුමක්ද?", "හෝමෝන බද්ධය හෙවත් ජැඩෙල් / ඉම්ප්ලානොන් (Subdermal Implants)", "මුඛ පෙති", "ලූපය", "වාසෙක්ටමි", "සම යට තැන්පත් කරන කුඩා කරල මගින් දිගුකාලීනව හෝමෝන ස්‍රාවය කර ගැබ් ගැනීම් වළක්වයි."),
        q("ගර්භාෂය තුළ තැන්පත් කරන හෝමෝන රහිත තඹ අඩංගු උපත් පාලන උපකරණය කුමක්ද?", "ගර්භාෂගත උපකරණය හෙවත් ලූපය (IUCD / Copper-T)", "කොන්ඩම්", "හෝමෝන එන්නත", "මුඛ පෙති", "තඹ ලූපය මගින් ශුක්‍රාණු විනාශ කර ගර්භාෂ බිත්තියේ කලලය රෝපණය වීම වළක්වයි."),
        q("මව්කිරි දෙන මව්වරුන්ට පමණක් මුල් මාස 6 තුළ ස්වභාවිකව ඩිම්බ මෝචනය ප්‍රමාද වීම හඳුන්වන්නේ කෙසේද?", "ස්තන්‍යපායී ඇමෙනෝරියා ක්‍රමය (LAM — Lactational Amenorrhea Method)", "දින දර්ශන ක්‍රමය", "උෂ්ණත්ව ක්‍රමය", "බාහිර මෝචනය", "නිරන්තරයෙන් මව්කිරි දීමේදී පිටවන ප්‍රෝලැක්ටින් හෝමෝනය මගින් ඩිම්බ මෝචනය තාවකාලිකව මර්දනය වේ."),
        q("කාන්තාවකගේ ශරීර උෂ්ණත්වය ඩිම්බ මෝචනයත් සමග සුළු වශයෙන් ඉහළ යාම නිරීක්ෂණය කරන ස්වභාවික ක්‍රමය කුමක්ද?", "පාදස්ථ ශරීර උෂ්ණත්ව ක්‍රමය (Basal Body Temperature Method)", "දින දර්ශන ක්‍රමය", "ස්පන්දන ක්‍රමය", "මුත්‍ර පරීක්ෂාව", "ප්‍රොජෙස්ටරෝන් හෝමෝනය නිසා ඩිම්බ මෝචනයෙන් පසු උදෑසන විවේකී ශරීර උෂ්ණත්වය සෙල්සියස් 0.3-0.5කින් ඉහළ යයි."),
        q("ලිංගාශ්‍රිත ඉන්නන් (Genital Warts) රෝග ලක්ෂණ ප්‍රජනක ප්‍රදේශවල ඇති කරන වෛරසය කුමක්ද?", "මානව පැපිලෝමා වෛරසය (HPV — 6 සහ 11 ප්‍රභේද)", "HIV වෛරසය", "හෙපටයිටිස් වෛරසය", "ඩෙංගු වෛරසය", "HPV මගින් ලිංගාශ්‍රිතව මල්ගෝවා මලක හැඩැති වේදනා රහිත ගැටිති හෙවත් ඉන්නන් හටගනී."),
        q("සිෆිලිස් (Syphilis) රෝගයේ තුන්වන අවධියේදී (Tertiary Syphilis) සිදුවිය හැකි බරපතළ හානිය කුමක්ද?", "මොළය, හෘදය සහ ස්නායු පද්ධතිය විනාශ වී අංශභාගය හෝ මරණය සිදුවීම", "හිසකෙස් වැවීම", "උස යාම", "දත් කැක්කුම පමණක්", "වසර ගණනාවක් ප්‍රතිකාර නොකළ සිෆිලිස් රෝගය මගින් මොළය විනාශ වී ස්නායු සිෆිලිස් (Neurosyphilis) තත්ත්වය ඇතිවේ."),
        q("ගොනෝරියා ආසාදිත මවකගෙන් බිහිවන බිළිඳාගේ ඇස්වලට විෂබීජ ඇතුළු වීමෙන් හටගත හැකි සංකූලතාව කුමක්ද?", "නොමේරූ අන්ධභාවය (Ophthalmia Neonatorum)", "කන් ඇසීම නැතිවීම", "පාද අස්ථි බිඳීම", "දත් නොඒම", "උපත් ඇළ ඔස්සේ පැමිණෙන විට බිළිඳාගේ ඇස් ආසාදනය වී අන්ධභාවයට පත්විය හැකි බැවින් ප්‍රතිජීවක බිංදු දමයි."),
        q("ශ්‍රී ලංකාවේ සියලුම ගර්භණී මව්වරුන්ට ප්‍රසව සායනවලදී අනිවාර්යයෙන්ම සිදුකරන රුධිර පරීක්ෂණ දෙක මොනවාද?", "VDRL (සිෆිලිස් සඳහා) සහ HIV පරීක්ෂාව", "මැලේරියා පරීක්ෂාව පමණි", "පිළිකා පරීක්ෂාව", "ඩෙංගු පරීක්ෂාව", "මවගෙන් දරුවාට සිෆිලිස් හෝ HIV සම්ප්‍රේෂණය වීම වළක්වා ගැනීමට මුල් සායනයේදීම මෙම පරීක්ෂණ නොමිලේ කෙරේ."),
        q("මවගෙන් දරුවාට HIV බෝවීම වැළැක්වීමේ ජාතික වැඩසටහන හඳුන්වන්නේ කෙසේද?", "PMTCT වැඩසටහන (Prevention of Mother-to-Child Transmission)", "DOTS වැඩසටහන", "EPI වැඩසටහන", "IMCI වැඩසටහන", "ශ්‍රී ලංකාව මවගෙන් දරුවාට HIV සහ සහජ සිෆිලිස් බෝවීම තුරන් කළ රටක් ලෙස WHO සහතිකය ලබා ඇත."),
        q("පිරිමි දරුවෙකුගේ වෘෂණ කෝෂ නිසි පරිදි වෘෂණ කෝෂ බෑගය තුළට නොපැමිණ උදරයේ සිරවී පැවතීම හඳුන්වන්නේ කෙසේද?", "අක්‍රිප්ටෝකීඩතාව හෙවත් අප්‍රතිපාදිත වෘෂණ (Cryptorchidism)", "හර්නියා", "හයිඩ්‍රොසීල්", "වාසෙක්ටමි", "උදර උෂ්ණත්වය නිසා ශුක්‍රාණු සෛල විනාශ වී අනාගතයේ වඳභාවය හා පිළිකා අවදානම ඇතිවිය හැකි බැවින් ශල්‍යකර්මයකින් පහත් කරයි."),
        q("වෘෂණ කෝෂ වටා ඇති පටල අතර තරලය පිරීම නිසා වෘෂණ කෝෂ ඉදිමීම හඳුන්වන්නේ කෙසේද?", "හයිඩ්‍රොසීල් හෙවත් ජල කෝෂය (Hydrocele)", "අපස්මාරය", "හර්පීස්", "සිෆිලිස්", "වෘෂණ කෝෂය තුළ වතුර පිරීම Hydrocele වන අතර සරල වෛද්‍ය ප්‍රතිකාර මගින් සුව කළ හැක."),
        q("උදර බිත්තියේ දුර්වල ස්ථානයක් තුළින් බඩවැල් කොටසක් වෘෂණ කෝෂ බෑගය දෙසට නෙරා ඒම කුමක්ද?", "වෘෂණ ආශ්‍රිත හර්නියා (Inguinal Hernia)", "හයිඩ්‍රොසීල්", "උළුක්කුව", "පිළිකාව", "බර එසවීම හෝ උපතින් ඇති දුර්වලතා නිසා බඩවැල් නෙරා ඒම හර්නියා තත්ත්වයයි."),
        q("කාන්තාවන් තුළ ආර්තවයට පෙර දින කිහිපයේදී හටගන්නා හිසරදය, පියයුරු තද ගතිය සහ කේන්ති යාම හඳුන්වන්නේ කෙසේද?", "ප්‍රාග් ආර්තව සින්ඩ්‍රෝමය (PMS — Premenstrual Syndrome)", "ආර්තවාභාවය", "ගර්භණීභාවය", "විජලනය", "හෝමෝන මට්ටම්වල ක්ෂණික පහත වැටීම නිසා ආර්තවයට පෙර කායික හා චිත්තවේගීය අපහසුතා මතුවේ."),
        q("ආර්තව සමයේදී යටි බඩේ සහ කොන්දේ හටගන්නා දැඩි වේදනාකාරී කැක්කුම වෛද්‍ය විද්‍යාත්මකව හඳුන්වන්නේ කෙසේද?", "ඩිස්මෙනෝරියා හෙවත් ආර්තව වේදනාව (Dysmenorrhoea)", "ඇමෙනෝරියා", "මෙනාකී", "මෙනපෝස්", "ගර්භාෂ පේශි සංකෝචනයට බලපාන ප්‍රොස්ටැග්ලැන්ඩින් හෝමෝන නිසා මෙම වේදනාව හටගනී."),
        q("ආර්තව වේදනාව (Dysmenorrhoea) සමනය කර ගැනීම සඳහා නිවසේදී කළ හැකි සරල ප්‍රතිකාරය කුමක්ද?", "යටි බඩ ප්‍රදේශය උණුසුම් වතුර බෝතලයකින් තැවීම සහ ප්‍රමාණවත් විවේකය", "අයිස් වතුර බීම", "දැඩිව බඩට පහර දීම", "ආහාර නොගෙන සිටීම", "උණුසුම් තැවීම මගින් ගර්භාෂ මාංශ පේශි ලිහිල් වී රුධිර සංසරණය වැඩි වී වේදනාව සමනය වේ."),
        q("යෝනි මාර්ගයේ සනීපාරක්ෂාව රැකගැනීම සඳහා සුවඳ විලවුන්, කෘත්‍රිම සේදුම් දියර (Douching) නිතර භාවිත නොකළ යුත්තේ මන්ද?", "යෝනි මාර්ගයේ සිටින හිතකර ලැක්ටොබැසිලස් බැක්ටීරියා විනාශ වී ස්වභාවික ආම්ලික ආරක්ෂාව බිඳ වැටෙන බැවින්", "සුවඳ වැඩිවන නිසා", "සම පැහැපත් වන නිසා", "කිසිදු හානියක් නැති නිසා", "ස්වභාවික ක්ෂුද්‍ර ජීවී සමතුලිතතාවය බිඳ වැටීමෙන් අහිතකර බැක්ටීරියා හා දිලීර ආසාදන පහසුවෙන් හටගනී."),
        q("යෝනි මාර්ගය පිරිසිදු කිරීමේදී වැසිකිලි භාවිතයෙන් පසු පිස දැමිය යුතු නිවැරදි දිශානතිය කුමක්ද?", "ඉදිරිපස සිට පසුපස දෙසට (Front to Back)", "පසුපස සිට ඉදිරිපසට", "එහා මෙහා අතුල්ලා", "කැමති ඕනෑම පැත්තකට", "පසුපස සිට ඉදිරියට පිස දැමුවහොත් ගුද මාර්ගයේ ඇති E. coli බැක්ටීරියා මුත්‍ර හා ප්‍රජනක මාර්ගයට ඇතුළු වේ."),
        q("කාන්තාවන් තුළ බහුලව මුත්‍ර මාර්ග ආසාදන (UTI) හටගැනීමට බලපාන ප්‍රධාන ව්‍යුහ විද්‍යාත්මක හේතුව කුමක්ද?", "කාන්තාවන්ගේ මුත්‍ර මාර්ගය (Urethra) පිරිමින්ට වඩා කෙටි වීම සහ ගුද මාර්ගයට ආසන්නව පිහිටීම", "ජලය වැඩිපුර බීම", "වැඩිපුර ඇවිදීම", "රුධිරය අඩුවීම", "කෙටි මුත්‍ර මාර්ගය නිසා බාහිර විෂබීජවලට පහසුවෙන් මුත්‍ර ආශයිකාව දක්වා ගමන් කළ හැක."),
        q("මුත්‍ර මාර්ග ආසාදන (UTI) වළක්වා ගැනීම සඳහා අනුගමනය කළ යුතු ප්‍රධානතම සෞඛ්‍ය පුරුද්ද කුමක්ද?", "දිනපතා ප්‍රමාණවත් පරිදි පිරිසිදු ජලය පානය කිරීම සහ මුත්‍ර පිටකිරීමේ අවශ්‍යතාව පාලනය කරගෙන නොසිටීම", "පැණි බීම පමණක් බීම", "ජලය නොබී සිටීම", "මුත්‍ර වැඩිවේලාවක් රඳවා ගැනීම", "නිතර මුත්‍ර පිටවීම මගින් මුත්‍ර මාර්ගයේ ඇති බැක්ටීරියා ස්වභාවිකව සේදී ඉවත් වේ."),
        q("ශ්‍රී ලංකාවේ වයස අවුරුදු 18ට අඩු දරුවන්ට සිදුවන ලිංගික හිංසනයන් හා අපයෝජනයන් පිළිබඳ ක්ෂණිකව දැනුම් දිය හැකි ළමා උපකාරක දුරකථන අංකය කුමක්ද?", "1929 (ජාතික ළමා ආරක්ෂක අධිකාරිය)", "119", "1990", "1919", "1929 අංකය පැය 24 පුරා ළමා හිංසන හා අපයෝජන වැළැක්වීමට නොමිලේ ක්‍රියාත්මක වේ."),
        q("නව යොවුන් වියේදී අන්තර්ජාලය හා සමාජ මාධ්‍ය හරහා සිදුවන අනවශ්‍ය ලිංගික බලපෑම් හා ඡායාරූප ඉල්ලීම්වලදී කළ යුත්තේ කුමක්ද?", "කිසිදු පෞද්ගලික ඡායාරූපයක් හුවමාරු නොකර වහාම දෙමාපියන්, ගුරුවරුන් හෝ පොලිසිය දැනුවත් කිරීම", "ඔවුන් කියන දේ කිරීම", "රහසක් ලෙස තබා ගැනීම", "මුදල් ගෙවීම", "බ්ලැක්මේල් කිරීම්වලට හසු නොවී වැඩිහිටි සහය ලබාගැනීමෙන් විශාල අනතුරු වළක්වා ගත හැක."),
        q("තම ශරීරයේ රහස්‍ය අවයව අන්‍යයන් විසින් අනවශ්‍ය ලෙස ස්පර්ශ කිරීමට උත්සාහ කරන විට දරුවන් ක්‍රියා කළ යුතු ආකාරය කුමක්ද?", "දැඩිව 'එපා' යැයි පවසා එම ස්ථානයෙන් ඉවත් වී විශ්වාසවන්ත වැඩිහිටියෙකුට පැවසීම (Safe and Unsafe Touch)", "නිහඬව සිටීම", "ලැජ්ජාවෙන් සැඟවීම", "තෑගි ලබාගැනීම", "අනාරක්ෂිත ස්පර්ශයන් හඳුනාගෙන තමාගේ ශරීරයේ ආරක්ෂාව තහවුරු කරගැනීම දරුවා සතු අයිතියකි."),
        q("ප්‍රජනක සෞඛ්‍යය පිළිබඳ විවෘතව හා විද්‍යාත්මකව සාකච්ඡා කිරීම සමාජයකට වැදගත් වන්නේ මන්ද?", "ලිංගික අපයෝජන, අනවශ්‍ය ගැබ් ගැනීම් සහ ලිංගාශ්‍රිත රෝගවලින් තොර නිරෝගී සදාචාර සම්පන්න පරපුරක් බිහි කිරීමට", "මිථ්‍යා විශ්වාස වැඩි කිරීමට", "සමාජය විනාශ කිරීමට", "විභාග පමණක් සමත් වීමට", "විද්‍යාත්මක අවබෝධය මගින් පුද්ගල ආත්ම ගරුත්වය, සමානාත්මතාවය හා පවුල් සෞඛ්‍යය මනාව සුරක්ෂිත වේ."),
        q("නව යොවුන් වියේ කායික හා මානසික ගැටලු සඳහා උපදෙස් ලබාගත හැකි ශ්‍රී ලංකා සෞඛ්‍ය අමාත්‍යාංශයේ යොවුන් සෞඛ්‍ය සායන හඳුන්වන්නේ කෙසේද?", "යෞවන පියස (Yowun Piyasa Clinics)", "ළමා සායන", "වැඩිහිටි සායන", "විකලාංග සායන", "රජයේ රෝහල්වල පිහිටි යෞවන පියස මගින් යෞවනයන්ට මිත්‍රශීලී සෞඛ්‍ය හා උපදේශන සේවාවන් සපයයි."),
        q("නිරෝගී ප්‍රජනක පද්ධතියක් පවත්වා ගැනීම සඳහා නව යොවුන් වියේදී අනුගමනය කළ යුතු ජීවන රටාව කුමක්ද?", "පෝෂ්‍යදායී සමබල ආහාර ගැනීම, ක්‍රියාශීලී ක්‍රීඩාවල යෙදීම සහ මත්ද්‍රව්‍යවලින් සම්පූර්ණයෙන්ම වැළකී සිටීම", "නිරාහාරව සිටීම", "දිවා රෑ නොබලා දුරකථන භාවිතය", "විටමින් පෙති පමණක් බීම", "සමබල පෝෂණය හා යහපත් චර්යාවන් මගින් හෝමෝන ක්‍රියාකාරිත්වය හා සමස්ත ප්‍රජනක සෞඛ්‍යය මනාව පවත්වා ගත හැක."),
        q("ආර්තව චක්‍රය අක්‍රමවත් වීම හෝ මාස ගණනාවක් ඔසප් නොවීමකදී (Secondary Amenorrhoea) කළ යුතු සුදුසුම ක්‍රියාව කුමක්ද?", "සුදුසුකම් ලත් ප්‍රසව හා නාරිවේද වෛද්‍යවරයෙකු හමුවී නිසි පරීක්ෂාවකට ලක්වීම", "නොසලකා හැරීම", "අසල්වැසියන්ගේ උපදෙස් මත බෙහෙත් බීම", "අධික ලෙස ව්‍යායාම කිරීම", "හෝමෝන හෝ කායික ගැටලු කල්තියා හඳුනාගෙන නිසි ප්‍රතිකාර ලබාගත යුතුය."),
        q("ස්ත්‍රී පුරුෂ සමාජභාවය (Gender) සහ ජෛව විද්‍යාත්මක ලිංගිකත්වය (Sex) අතර වෙනස කුමක්ද?", "ලිංගිකත්වය ජෛව විද්‍යාත්මක සාධක මත තීරණය වන අතර ස්ත්‍රී පුරුෂ සමාජභාවය සමාජය විසින් ගොඩනගන ලද භූමිකාවකි", "දෙකම එකම අර්ථය දරයි", "ලිංගිකත්වය සමාජයෙන් තීරණය වේ", "කිසිදු වෙනසක් නැත", "Sex යනු වර්ණදේහ හා අවයව අනුව තීරණය වන ජීව විද්‍යාත්මක ලක්ෂණය වන අතර Gender යනු සමාජීය සංකල්පයකි."),
        q("නව යොවුන් වියේදී ප්‍රජනක සෞඛ්‍යය සුරැකීමේ අවසාන ඉලක්කය කුමක්ද?", "කායික, මානසික හා සමාජයීය වශයෙන් පූර්ණ සුවපත්භාවයෙන් යුතු වගකීම් සහගත වැඩිහිටියෙකු බවට පත්වීම", "ධනවත් වීම පමණක්", "ශරීරයේ බර අඩු කර ගැනීම", "තරගවලින් ජයගැනීම පමණි", "ප්‍රජනක සෞඛ්‍යය යනු හුදෙක් රෝගවලින් තොරවීම නොව ප්‍රජනක පද්ධතිය ආශ්‍රිත පූර්ණ කායික, මානසික හා සමාජ යහපැවැත්මයි."),
        q("මානව ඩිම්බ කෝෂය තුළ ප්‍රාථමික ඩිම්බ සෛල (Primary oocytes) කොපමණ සංඛ්‍යාවක් ගැහැනු දරුවෙකු උපදින විටම අඩංගු වී තිබේද?", "උපතේදීම ඩිම්බ සෛල මිලියන 1-2ක් පමණ අඩංගු වේ", "ඩිම්බ 100ක් පමණි", "උපතේදී ඩිම්බ කිසිවක් නැත", "බිලියනයක් අඩංගු වේ", "ගැහැනු ළමයෙකු උපදින විටම ඇගේ ජීවිත කාලයටම අවශ්‍ය සියලු ප්‍රාථමික ඩිම්බ සෛල ඩිම්බ කෝෂවල පවතී."),
        q("කාන්තාවකගේ මුළු ප්‍රජනක ආයු කාලය (වයස 15-50) තුළ පරිණත වී මුදාහරිනු ලබන සම්පූර්ණ ඩිම්බ සංඛ්‍යාව ආසන්න වශයෙන් කීයද?", "ඩිම්බ 400 සිට 500 දක්වා පමණි", "ඩිම්බ මිලියනයක්", "ඩිම්බ 50ක්", "ඩිම්බ 5000ක්", "ජීවිත කාලය තුළ මෝචනය වන්නේ ඩිම්බ 400-500ක් පමණක් වන අතර අනෙක් ඩිම්බ ස්වභාවිකව විනාශ වී යයි."),
        q("එක් ඩිම්බ මෝචන චක්‍රයකදී සාමාන්‍යයෙන් පරිණත වී පිටවන්නේ ඩිම්බ සෛල කීයක්ද?", "එක් ඩිම්බයක් පමණි (කලාතුරකින් දෙකක්)", "ඩිම්බ 10ක්", "ඩිම්බ සියයක්", "ඩිම්බ 4ක්", "සාමාන්‍යයෙන් මසකට එක් ඩිම්බ කෝෂයකින් එක් පරිණත ඩිම්බයක් පමණක් මෝචනය වේ."),
        q("ශුක්‍රාණු ජනන ක්‍රියාවලියට (Spermatogenesis) තනි ශුක්‍රාණුවක් සම්පූර්ණයෙන් නිපදවීමට ගතවන සාමාන්‍ය දින ගණන කොපමණද?", "දින 64 සිට 74 දක්වා කාලයක්", "පැය 24ක්", "දින 7ක්", "වසරක්", "ප්‍රාථමික සෛලයක සිට පරිණත ශුක්‍රාණුවක් හැදීමට දින 64-74ක පමණ කාලයක් ගතවේ."),
        q("ඩිම්බ සෛලයක් ප්‍රමාණයෙන් ශුක්‍රාණුවකට වඩා බොහෝ විශාල වීමට ප්‍රධාන හේතුව කුමක්ද?", "සංසේචිත කලලයේ මුල් වර්ධනයට අවශ්‍ය පෝෂණය සපයන සෛල ප්ලාස්මය විශාල ප්‍රමාණයක් පැවතීම", "ඩිම්බයේ අස්ථි ඇති නිසා", "ශුක්‍රාණුවල ජලය නොමැති නිසා", "කිසිදු හේතුවක් නැත", "කලලයේ මුල් දින කිහිපයේ සෛල බෙදීමට අවශ්‍ය සියලු පෝෂ්‍ය පදාර්ථ ඩිම්බ සෛල ප්ලාස්මයේ ගබඩා වී ඇත."),
        q("ඩිම්බ සෛලයකට ස්වයංක්‍රීයව පිහිනා යාමේ හැකියාවක් නොමැති අතර එය පැපොලෝපීය නාලය ඔස්සේ ගමන් කරවන්නේ කුමක් මගින්ද?", "නාල බිත්තියේ ඇති පක්ෂ්මල අපිච්ඡදයේ තරංගාකාර චලනය මගින්", "රුධිර පීඩනය මගින්", "ගුරුත්වාකර්ෂණය මගින් පමණි", "වාතය මගින්", "පැපොලෝපීය නාලයේ ඇතුළත ඇති සියුම් පක්ෂ්ම කෙඳිවල ගැස්මෙන් ඩිම්බය ඉදිරියට තල්ලු කෙරේ."),
        q("ගර්භණී සමයේදී වැදෑමහ මගින් නිපදවන ගර්භණීභාවය මුත්‍ර පරීක්ෂාවෙන් හඳුනාගත හැකි හෝමෝනය කුමක්ද?", "මානව කෝරියෝනික් ගොනැඩොට්‍රොපින් (hCG) හෝමෝනය", "ඉන්සියුලින්", "ඇඩ්‍රිනලින්", "තයිරොක්සින්", "hCG හෝමෝනය නිපදවෙන්නේ ගැබ් ගැනීමෙන් පසුව වැදෑමහ වර්ධනය වන විට පමණි."),
        q("ගෘහස්ථ ගර්භණී පරීක්ෂණ කට්ටලවල (Urine Pregnancy Test Strip) පරීක්ෂා කරනු ලබන්නේ මුත්‍රවල ඇති කුමන හෝමෝනයද?", "hCG හෝමෝනය", "FSH හෝමෝනය", "LH හෝමෝනය", "ටෙස්ටොස්ටෙරෝන්", "මුත්‍රවල hCG හෝමෝනය හඳුනාගැනීම මගින් නිවසේදීම ගැබ්ගෙන ඇත්දැයි තහවුරු කරගත හැක."),
        q("ඩිම්බ මෝචනයෙන් පසු සංසේචනයක් සිදු නොවූ විට ප්‍රොජෙස්ටරෝන් හෝමෝන මට්ටම පහත වැටීමට හේතුව කුමක්ද?", "කහ දේහය (Corpus Luteum) ಕ್ಷය වී සුදු දේහයක් (Corpus Albicans) බවට පත්වීම", "ඩිම්බය විශාල වීම", "පිටියුටරිය විනාශ වීම", "ගර්භාෂය අතුරුදහන් වීම", "සංසේචනයක් නොවූ විට කහ දේහය ක්ෂය වී හෝමෝන ස්‍රාවය සම්පූර්ණයෙන්ම නතර වේ."),
        q("ප්‍රොජෙස්ටරෝන් සහ ඊස්ට්‍රජන් හෝමෝන මට්ටම් ක්ෂණිකව පහත වැටීම නිසා ගර්භාෂය තුළ සිදුවන ප්‍රතිඵලය කුමක්ද?", "ගර්භාෂ අන්තඃස්තරය බිඳ වැටී ආර්තව රුධිර වහනය ආරම්භ වීම", "ගර්භාෂය තවදුරටත් ඝන වීම", "කලලයක් සෑදීම", "ඩිම්බ මෝචනය වීම", "හෝමෝන අඩුවීම නිසා එන්ඩොමෙට්‍රියම් පටකය රඳවා ගත නොහැකිව බිඳ වැටී ඔසප් වීම හටගනී."),
        q("පියයුරු පිළිකා කල්තියා හඳුනාගැනීම සඳහා කාන්තාවන් මාසිකව තමා විසින්ම සිදුකරගත යුතු පරීක්ෂාව කුමක්ද?", "පියයුරු ස්වයං පරීක්ෂාව (BSE — Breast Self-Examination)", "එක්ස් කිරණ පරීක්ෂාව", "රුධිර පීඩනය බැලීම", "මුත්‍ර පරීක්ෂාව", "පියයුරුවල අසාමාන්‍ය ගැටිති හෝ සමේ වෙනස්කම් ඇත්දැයි මසකට වරක් ස්වයංව පරීක්ෂා කිරීම BSE වේ."),
        q("පියයුරු ස්වයං පරීක්ෂාව (BSE) සිදුකිරීමට වඩාත්ම සුදුසු කාලසීමාව කුමක්ද?", "ආර්තව රුධිර වහනය අවසන් වී දින 3 සිට 5 දක්වා කාලය තුළ", "ආර්තවය සිදුවන පළමු දිනයේ", "ආර්තවයට පෙර දිනයේ", "වසරකට එක් වරක්", "ආර්තවය අවසන් වූ පසු පියයුරුවල හෝමෝනමය තද ගතිය හා ඉදිමීම පහව යන බැවින් පරීක්ෂාව පහසු වේ."),
        q("ගැබ්ගෙල පිළිකා තත්ත්වයන් පූර්ව අවධියේදීම හඳුනාගැනීම සඳහා විවාහක කාන්තාවන්ට සිදුකරන සම්මත සායනික පරීක්ෂාව කුමක්ද?", "පැප් පරීක්ෂාව (Pap Smear Test)", "රුධිර සීනි පරීක්ෂාව", "ECG පරීක්ෂාව", "අස්ථි ඝනත්ව පරීක්ෂාව", "ගැබ්ගෙලෙන් ලබාගන්නා සෛල පරීක්ෂා කිරීමෙන් පිළිකා පූර්ව අවධියේදීම පහසුවෙන් හඳුනාගත හැක."),
        q("වෘෂණ කෝෂ පිළිකා කල්තියා හඳුනාගැනීම සඳහා පිරිමින් විසින් සිදුකළ යුතු ස්වයං පරීක්ෂාව කුමක්ද?", "වෘෂණ ස්වයං පරීක්ෂාව (TSE — Testicular Self-Examination)", "පපුව පරීක්ෂාව", "උදර ස්කෑන් පරීක්ෂාව", "ඇස් පරීක්ෂාව", "උණුසුම් ස්නානයකින් පසු වෘෂණවල අසාමාන්‍ය වේදනා රහිත ගැටිති ඇත්දැයි ඇඟිලිවලින් පරීක්ෂා කිරීම TSE වේ."),
        q("කාන්තාවන්ගේ ආර්තව චක්‍රයේදී ඩිම්බයක් නොමේරූ ෆොලිකලයක් තුළ වර්ධනය වීම උත්තේජනය කරන පිටියුටරි හෝමෝනය කුමක්ද?", "ෆොලිකල උත්තේජක හෝමෝනය (FSH)", "ප්‍රොලැක්ටින්", "ඔක්සිටොසින්", "තයිරොක්සින්", "FSH මගින් ඩිම්බ කෝෂයේ ෆොලිකල වර්ධනය කර ඊස්ට්‍රජන් ස්‍රාවය උත්තේජනය කරයි."),
        q("පිරිමින් තුළ ශුක්‍රාණු ජනන ක්‍රියාවලිය ඇරඹීමට ශුක්‍රධර නාලිකා උත්තේජනය කරන පිටියුටරි හෝමෝනය කුමක්ද?", "FSH හෝමෝනය", "LH හෝමෝනය", "ඉන්සියුලින්", "කෝටිසෝල්", "පිරිමින්ගේද FSH හෝමෝනය මගින් සර්ටෝලි සෛල උත්තේජනය කර ශුක්‍රාණු නිපදවීම සිදුකරයි."),
        q("ශ්‍රී ලංකාවේ වයස අවුරුදු 16-19 අතර යොවුන් දරුවන්ට ප්‍රජනක සෞඛ්‍යය පිළිබඳ නිවැරදි උපදෙස් ලබාගත හැකි නොමිලේ ඇමතුම් දුරකථන සේවාවක් වන්නේ කුමක්ද?", "1948 (සෞඛ්‍ය ප්‍රවර්ධන කාර්යාංශයේ සුවසැරිය උපකාරක සේවාව)", "119", "110", "1912", "1948 ක්ෂණික දුරකථන අංකය මගින් සෞඛ්‍ය උපදෙස් සහ තොරතුරු නොමිලේ ලබාගත හැක."),
        q("ලිංගික එක්වීමකින් තොරව සිපගැනීමෙන්, වැළඳගැනීමෙන් හෝ එකම වැසිකිලිය භාවිතයෙන් ගොනෝරියා හෝ සිෆිලිස් බෝවිය හැකිද?", "නැත, එම බැක්ටීරියාවලට බාහිර පරිසරයේ ජීවත් විය නොහැකි බැවින් බෝ නොවේ", "ඔව්, ඕනෑම ස්පර්ශයකින් බෝවේ", "ජලය හරහා බෝවේ", "සුළඟින් බෝවේ", "ලිංගාශ්‍රිත රෝගකාරක බැක්ටීරියා ශරීරයෙන් පිටත වියළි පරිසරයේදී විනාඩි කිහිපයකින් විනාශ වී යයි."),
        q("ශ්‍රී ලංකාවේ රුධිර බැංකුව මගින් පරිත්‍යාගශීලීන්ගෙන් ලබාගන්නා සියලුම රුධිර සාම්පල අනිවාර්යයෙන්ම පරීක්ෂා කරනු ලබන ආසාදන මොනවාද?", "HIV, හෙපටයිටිස් B, හෙපටයිටිස් C, සිෆිලිස් සහ මැලේරියාව", "දියවැඩියාව පමණි", "කොලෙස්ටරෝල් පමණි", "ගැස්ට්‍රයිටිස් පමණි", "ලබාගන්නා සෑම රුධිර බිංදුවක්ම මෙම භයානක රෝග පහ සඳහා පරීක්ෂා කර ආරක්ෂාව තහවුරු කරයි."),
        q("ශ්‍රී ලංකාවේ නිරෝගී පුද්ගලයෙකුට රුධිරය දීමෙන් (Blood donation) HIV ආසාදනය වීමේ අවදානමක් තිබේද?", "නැත, එක් අයෙකුට එක් වරක් පමණක් භාවිත කර විසි කරන විෂබීජහරණය කළ කටු භාවිත කරන බැවින්", "ඔව්, ඉතා ඉහළ අවදානමක් ඇත", "රුධිරය දුන් පසු රෝගය හැදේ", "ලේ දෙන සියල්ලන්ටම බෝවේ", "රුධිරය ලබාගැනීමට භාවිත කරන්නේ තනි භාවිත විෂබීජහරණය කළ උපකරණ බැවින් රුධිර පරිත්‍යාගශීලියාට කිසිදු රෝගයක් බෝ නොවේ."),
        q("යොවුන් වියේදී ප්‍රජනක සෞඛ්‍යය ආරක්ෂා කරගැනීමට ලිංගික සබඳතා ආරම්භ කිරීම විවාහය තෙක් කල් දැමීම (Abstinence) වැදගත් වන්නේ මන්ද?", "අනවශ්‍ය ගැබ් ගැනීම්, ලිංගාශ්‍රිත රෝග සහ මානසික පීඩාවලින් 100%ක්ම ආරක්ෂා වන එකම ක්‍රමය වන බැවින්", "එයින් ශරීරය දුර්වල වන නිසා", "එය නීති විරෝධී නිසා", "විභාග අසමත් වන නිසා", "ලිංගික සංසර්ගයෙන් වැළකී සිටීම (Abstinence) යනු ලිංගාශ්‍රිත රෝග හා ගැබ් ගැනීම්වලින් සම්පූර්ණයෙන්ම ආරක්ෂා වන එකම ක්‍රමයයි."),
        q("ලිංගාශ්‍රිත රෝගවලින් ආරක්ෂා වීමේ ABC මූලධර්මයේ A අකුරෙන් නියෝජනය වන වඩාත්ම විශ්වාසවන්ත පියවර කුමක්ද?", "වැළකී සිටීම (Abstinence)", "ඇල්කොහොල් බීම", "ආහාර පාලනය", "ඇවිදීම", "A යනු Abstinence හෙවත් අවදානම් ලිංගික ඇසුරෙන් වැළකී සිටීමයි."),
        q("ABC මූලධර්මයේ B අකුරෙන් අදහස් වන රැකවරණය කුමක්ද?", "තම විශ්වාසවන්ත එකම සහකරුට හෝ සහකාරියට පමණක් සීමා වීම (Be faithful)", "ලේ බැඳීම", "පොත් කියවීම", "බාධක දැමීම", "B යනු Be faithful හෙවත් එක් විශ්වාසවන්ත සහකරුවෙකුට පමණක් සීමා වීමයි."),
        q("ABC මූලධර්මයේ C අකුරෙන් නියෝජනය වන ආරක්ෂිත පියවර කුමක්ද?", "නිවැරදිව හා අඛණ්ඩව කොන්ඩම් භාවිතය (Condom use)", "පිරිසිදුකම", "සන්නිවේදනය", "සන්සුන් බව", "C යනු Condom භාවිතය මගින් ලිංගාශ්‍රිත ආසාදන අවම කර ගැනීමයි."),
        q("ප්‍රජනක අවයව ආශ්‍රිතව හටගන්නා අසාමාන්‍ය තුවාල, ගැටිති, දැවිල්ල හෝ දුර්ගන්ධ ශ්‍රාවයන් වහාම වෛද්‍යවරයෙකුට පෙන්වීම වැදගත් වන්නේ මන්ද?", "මුල් අවධියේදීම නිසි ප්‍රතිකාර ලබාගෙන බරපතළ සංකූලතා හා වඳභාවය වළක්වා ගැනීමට", "ලැජ්ජාව වැඩි කර ගැනීමට", "ශල්‍යකර්ම කර ගැනීමට", "මුදල් වියදම් කිරීමට", "කල්තියා ප්‍රතිකාර ගැනීමෙන් ලිංගික රෝග සුව කරගත හැකි අතර අනාගත ප්‍රජනක සෞඛ්‍යය සුරක්ෂිත වේ."),
        q("ශ්‍රී ලංකාවේ ගැබ්ගෙල පිළිකා මර්දනය සඳහා වයස අවුරුදු 35 සහ 45 වන කාන්තාවන්ට සුවනාරී සායනවලදී පවත්වන පරීක්ෂාව කුමක්ද?", "සුවනාරී සායන පැප් පරීක්ෂාව සහ HPV DNA පරීක්ෂාව", "රුධිර පීඩනය බැලීම පමණි", "ඇස් පෙනීම පරීක්ෂාව", "බර කිරා බැලීම පමණි", "රජයේ සුවනාරී සායන මගින් කාන්තාවන්ගේ ගැබ්ගෙල පිළිකා පූර්ව ලක්ෂණ නොමිලේ පරීක්ෂා කරයි."),
        q("පිරිමින්ගේ වෘෂණවලට තද පහරක් වැදුණු විට දැඩි වේදනාවක් දැනීමට හේතුව කුමක්ද?", "වෘෂණ කෝෂ තුළ සංවේදී ස්නායු අන්ත අතිවිශාල ප්‍රමාණයක් ඝනව පිහිටා තිබීම", "වෘෂණවල අස්ථි ඇති නිසා", "රුධිරය නොමැති නිසා", "පටක නොමැති නිසා", "වෘෂණ අතිශය සංවේදී අවයවයක් වන අතර ආරක්ෂාව සඳහා ස්නායු අන්ත බහුලව පිහිටයි."),
        q("ක්‍රීඩා කරන පිරිමි ක්‍රීඩකයන් (ක්‍රිකට්, හොකී, සටන් කලා) තම ප්‍රජනක අවයව ආරක්ෂා කර ගැනීමට පැළඳිය යුතු ආම්පන්නය කුමක්ද?", "ගාර්ඩ් එක හෙවත් ප්‍රජනක ආරක්ෂක ආවරණය (Abdominal Guard / L-guard)", "දණහිස් ආවරණ", "හිස් ආවරණ", "වැලමිට ආවරණ", "වේගයෙන් එන පන්දු හෝ පහරවලින් වෘෂණවලට සිදුවන මාරාන්තික හානි වැළැක්වීමට L-guard පලඳිය යුතුය."),
        q("දැඩි තද යට ඇඳුම් දිගු වේලාවක් ඇඳීම පිරිමින්ගේ ශුක්‍රාණු නිෂ්පාදනයට අහිතකර වන්නේ මන්ද?", "වෘෂණ කෝෂ සිරුරට තද වී උෂ්ණත්වය ඉහළ යාම නිසා ශුක්‍රාණු නිපදවීම හා සක්‍රීයතාව අඩුවන බැවින්", "ශරීරයේ බර අඩුවන නිසා", "උස යාම නතර වන නිසා", "කිසිදු හානියක් නැත", "තද ඇඳුම් නිසා වෘෂණවල උෂ්ණත්වය වැඩිවීම ශුක්‍රාණු ජනනයට සෘජුවම බාධා කරයි."),
        q("මත්පැන් සහ දුම්පානය පිරිමි ප්‍රජනක පද්ධතියට අහිතකර ලෙස බලපාන්නේ කෙසේද?", "ශුක්‍රාණු ප්‍රමාණය අඩුවීම, විකෘති ශුක්‍රාණු බිහිවීම සහ ලිංගික බෙලහීනතාව ඇතිවීම", "ශුක්‍රාණු වේගවත් වීම", "මාංශ පේශි වර්ධනය", "ආයු කාලය වැඩිවීම", "නිකොටින් සහ මධ්‍යසාර මගින් ශුක්‍රාණුවල DNA වලට හානි සිදුවන අතර හෝමෝන මට්ටම පහත හෙළයි."),
        q("දුම්පානය කරන කාන්තාවන්ගේ ප්‍රජනක පද්ධතියට සිදුවන අහිතකර බලපෑම කුමක්ද?", "ඩිම්බවල ගුණාත්මකභාවය අඩුවීම, කලල විකෘතිතා සහ අකාල ආර්තවාභාවය ඇතිවීම", "ඩිම්බ වැඩිපුර නිපදවීම", "රුධිරය පිරිසිදු වීම", "ආහාර රුචිය වැඩිවීම", "දුම්කොළ විෂ මගින් ඩිම්බ කෝෂවල සෛල විනාශ වී නොමේරූ ආර්තවාභාවයට පත්විය හැක."),
        q("ගර්භණී සමයේදී මවගේ උදරය තුළ කලලයේ චලනයන් මවට ප්‍රථම වරට දැනීම හඳුන්වන්නේ කෙසේද?", "ක්විකනිං හෙවත් දරු සෙලවීම (Quickening)", "රෝපණය", "ඩිම්බ මෝචනය", "ප්‍රසූතිය", "කලලය අත් පා චලනය කිරීම මවට ප්‍රථම වරට දැනීම Quickening වේ."),
        q("සාමාන්‍යයෙන් මවට දරු සෙලවීම (Quickening) ප්‍රථම වරට දැනෙන්නේ ගර්භණී සමයේ කුමන සතියේදීද?", "16 වන සිට 20 වන සතිය අතර කාලයේදී", "පළමු සතියේදී", "38 වන සතියේදී", "40 වන සතියේදී", "සාමාන්‍යයෙන් ගර්භණී සමයේ 4-5 වන මාසවලදී (සති 16-20) දරු සෙලවීම පැහැදිලිව දැනේ."),
        q("සාමාන්‍ය සම්පූර්ණ මානව ගර්භණී කාලය (Gestation Period) සති කීයකින් සමන්විත වේද?", "සති 40කි (දින 280ක් හෙවත් මාස 9යි දින 7ක්)", "සති 20කි", "සති 50කි", "සති 30කි", "අවසාන ආර්තවයේ පළමු දින සිට ගණන් කළ විට සාමාන්‍ය ගර්භණී කාලය සති 40කි."),
        q("ගර්භණී සමයේ 37 වන සතිය සම්පූර්ණ වීමට පෙර බිහිවන දරුවන් හඳුන්වන්නේ කෙසේද?", "නොමේරූ ළදරුවන් (Preterm / Premature Babies)", "පරිණත ළදරුවන්", "අධිපරිණත ළදරුවන්", "සාමාන්‍ය ළදරුවන්", "සති 37ට පෙර උපදින දරුවන් නොමේරූ ළදරුවන් ලෙස විශේෂ දැඩි සත්කාර ඒකකවල රඳවයි."),
        q("නොමේරූ දරුවන්ගේ පෙනහලු පරිණත නොවීම නිසා ඇතිවන ශ්වසන අපහසුතා තත්ත්වය කුමක්ද?", "නවජ ශ්වසන අපහසුතා සින්ඩ්‍රෝමය (NRDS)", "ඇදුම", "ක්ෂය රෝගය", "පීනස", "පෙනහලුවල සර්ෆැක්ටන්ට් ද්‍රව්‍යය නිසි පරිදි නිපදවී නොමැති වීම නිසා ගර්ත ඇලී යාම NRDS තත්ත්වයයි."),
        q("මව්කිරි දීමෙන් මවට ලැබෙන ප්‍රධාන සෞඛ්‍යමය වාසිය කුමක්ද?", "පියයුරු සහ ඩිම්බ කෝෂ පිළිකා ඇතිවීමේ අවදානම සැලකිය යුතු ලෙස අඩුවීම", "ශරීරය දුර්වල වීම", "අස්ථි කැඩීම", "රුධිර පීඩනය වැඩිවීම", "මව්කිරි දෙන මව්වරුන්ට පසුකාලීනව පියයුරු හා ඩිම්බ කෝෂ පිළිකා වැළඳීමේ සම්භාවිතාව ඉතා අඩුය."),
        q("මව්කිරි දීම මගින් මව සහ බිළිඳා අතර ඇතිවන මානසික බැඳීම හඳුන්වන්නේ කෙසේද?", "මාතෘ-ළමා සබැඳියාව (Mother-infant bonding)", "අවිශ්වාසය", "දුරස් වීම", "ආත්මාර්ථකාමිත්වය", "සම සමග ගැටීම (Skin-to-skin touch) සහ මව්කිරි දීම මගින් ඔක්සිටොසින් හෝමෝනය ශ්‍රාවය වී ප්‍රබල ආදරණීය බැඳීමක් ඇතිවේ."),
        q("දරුවෙකු ප්‍රසූත කිරීමට කාන්තාවකගේ සිරුර කායිකව හා මානසිකව වඩාත් යෝග්‍ය වන්නේ කුමන වයස් පරාසයේදීද?", "අවුරුදු 20 සිට 35 දක්වා වූ පරිණත වයස් සීමාවේදී", "අවුරුදු 12 සිට 15 දක්වා", "අවුරුදු 45ට පසු", "අවුරුදු 10දී", "වයස 20-35 අතර කාලය දරු ප්‍රසූතියක් සඳහා සංකූලතා අවම වඩාත්ම සුරක්ෂිත වයස් කාණ්ඩයයි."),
        q("වයස අවුරුදු 35න් පසු පළමු දරු උපත සිදුකිරීමේදී කලලයට ඇතිවිය හැකි ප්‍රධාන ජානමය අවදානම කුමක්ද?", "ඩවුන් සින්ඩ්‍රෝමය (Down Syndrome) වැනි වර්ණදේහ අසාමාන්‍යතා", "උස වැඩිවීම", "ඇස් පෙනීම වැඩිවීම", "දත් ඉක්මනින් ඒම", "මවගේ වයස වැඩිවත්ම ඩිම්බවල ඌනන විභාජන දෝෂ නිසා ඩවුන් සින්ඩ්‍රෝමය ඇතිවීමේ අවදානම ඉහළ යයි."),
        q("ඩවුන් සින්ඩ්‍රෝමය (Down Syndrome) හටගන්නේ කුමන වර්ණදේහයේ විකෘතිතාවක් නිසාද?", "21 වන වර්ණදේහය ත්‍රිත්වයක් ලෙස පිහිටීම (Trisomy 21)", "1 වන වර්ණදේහය", "ලිංග වර්ණදේහය", "10 වන වර්ණදේහය", "සාමාන්‍ය යුගලයක් වෙනුවට 21 වන වර්ණදේහයෙන් පිටපත් 3ක් (Trisomy 21) පැවතීම ඩවුන් සින්ඩ්‍රෝමයයි."),
        q("නව යොවුන් වියේදී ඇතිවන ප්‍රේම සබඳතාවලදී ලිංගික සබඳතාවලට එළඹීමට වඩා වැදගත් වන්නේ කුමක්ද?", "අන්‍යෝන්‍ය ගෞරවය, අවබෝධය හා අධ්‍යාපනය සම්පූර්ණ කර ගැනීම", "අනෙකා පාලනය කිරීම", "සැඟවුණු ලිංගික චර්යා", "පවුලේ අයගෙන් ඈත් වීම", "නව යොවුන් වියේ සබඳතාවල පදනම විය යුත්තේ අනාගත අරමුණු ජයගැනීමට එකිනෙකා ධෛර්යමත් කර ගැනීමයි."),
        q("සහකරුවෙකු ලිංගික එක්වීමකට බලපෑම් කරන විට 'නැත' යැයි පැවසීමෙන් ආදරය අඩු නොවන බව තේරුම් ගැනීම අයත් වන්නේ කුමන සංකල්පයටද?", "සෞඛ්‍ය සම්පන්න සබඳතා සීමා (Healthy Relationship Boundaries)", "සබඳතාව බිඳ දැමීම", "බියගුලුකම", "ආත්මාර්ථය", "තමාගේ ශරීරයේ ස්වාධීනත්වය හා තීරණ ගැනීමේ අයිතියට ගරු කරන සබඳතාවක් නිරෝගී සබඳතාවකි."),
        q("පාසල් සෞඛ්‍ය අධ්‍යාපනය තුළ ප්‍රජනක සෞඛ්‍යය ඇතුළත් කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?", "තරුණ පරපුරට විද්‍යාත්මක සාක්ෂි පදනම් කරගත් නිවැරදි තීරණ ගැනීමට දැනුම හා ආකල්ප ලබාදීම", "ලැජ්ජාව වැඩි කිරීම", "සම්ප්‍රදාය බිඳ දැමීම", "ශාරීරික පීඩාව", "නිවැරදි ලිංගික හා ප්‍රජනක සෞඛ්‍ය අධ්‍යාපනය මගින් යෞවනයන් අනතුරුවලින් හා වැරදි තොරතුරුවලින් ආරක්ෂා කෙරේ."),
        q("යොවුන් වියේ පසුවන දරුවෙකුට තම සිරුර පිළිබඳව හෝ මනස පිළිබඳව ඇතිවන ගැටලුවකදී නොපැකිලිව කතා කළ හැකි හොඳම පරිසරය කුමක්ද?", "දෙමාපියන් සහ ගුරුවරුන් සමග ඇති මිත්‍රශීලී විවෘත සන්නිවේදන පරිසරය", "අඳුරු කාමරයක්", "අන්තර්ජාල කතාබස් පමණක්", "අනවසර වෙබ් අඩවි", "විශ්වාසවන්ත වැඩිහිටියන් සමග විවෘතව කතා කිරීමෙන් බොහෝ ගැටලුවලට සැබෑ විසඳුම් ලබාගත හැක.")
    )
}
